cd /workspace/project && python3 << 'EOF'
import paramiko
client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect("46.202.154.25", 22, "root", "2N00py123+++")
# Get current full nginx config
stdin, stdout, stderr = client.exec_command("cat /etc/nginx/sites-enabled/arelorian.de")
print("Current config:\n", stdout.read().decode())
client.close()
EOF
Current config:
 server {
    listen 80;
    listen [::]:80;
    server_name arelorian.de www.arelorian.de;
    location /.well-known/acme-challenge/ { root /var/www/html; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name arelorian.de www.arelorian.de;
    ssl_certificate /etc/letsencrypt/live/arelorian.de/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/arelorian.de/privkey.pem;
    root /opt/areloria/client/dist;
    index index.html;
    gzip on;
    gzip_types text/plain text/css application/javascript application/json image/svg+xml;
    location / { try_files $uri /index.html; }
    location /assets/ { expires 1y; add_header Cache-Control "public"; }

    location /ws {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    location /client-config.json {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }

    location /world {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
    }

    location /api {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
